usage.code:
import { PixelSwap } from "solen-design/react";

<PixelSwap
  pattern="pointer"
  pixelSize={48}
  pixelRadius={18}
  pixelSpin={90}
  duration={400}
  pixelDuration={350}
  bounce={0.4}
  trigger="hover"
  aspectRatio="16 / 10"
  onComplete={(active) => console.log("settled on", active ? "second" : "first")}
  firstContent={<div style={{ background: "#312e81" }} />}
  secondContent={<div style={{ background: "#0f766e" }} />}
/>
